-- V11: Demo stage history — the initial "job opened" row for every seeded job,
-- plus the real Stage Change Log entries transcribed from the workbook (marked
-- 'Seeded' there too — the workbook itself notes these are reconstructed
-- estimates for the sample data, not live-logged events).

-- Initial NOT_STARTED entry for every seeded job (from_stage_id NULL = job creation).
SELECT j.id, NULL, (SELECT id FROM fabrication_stages WHERE code='NOT_STARTED'), j.job_card_date, 0,
       (SELECT id FROM users WHERE username='admin'), FALSE, 'Job card opened'
FROM fabrication_jobs j;

-- Helper note: (job_id via vehicle_id subquery, from/to via code subquery, admin as actor)
